項目=燕麥加牛奶和水果：有纖維、飽足感夠；全麥吐司加蛋：簡單又有蛋白質；地瓜加無糖豆漿：台灣便利商店就買得到；優格加堅果：五分鐘搞定；蛋餅加無糖茶：台式早餐店的經典
