@寵物|養什麼寵物,適合養的寵物|推薦
項目=貓：獨立、愛乾淨，適合上班族；狗：忠心、熱情，但需要每天散步和陪伴；兔子：安靜可愛，需要空間和牧草；倉鼠：照顧簡單，但晚上比較活躍；魚：療癒、不吵，但要維護水質
首選=如果你常不在家，我推薦貓，因為牠們比較能自己待著；如果你想要每天一起出門運動的夥伴，就是狗
問=你住的地方大嗎？每天有多少時間能陪牠？
@無聊|好無聊,沒事做|推薦
