故事=年老的李爾王要把國土分給三個女兒，誰說最愛他就分得多。大女兒、二女兒滿口甜言蜜語，小女兒考狄利婭老實說話反被趕走。拿到國土後，兩個姊姊卻把父親趕出去，李爾王在暴風雨中發瘋
