年代=1862 年
簡介=雨果的代表作，寫十九世紀法國底層人民的苦難和救贖
故事=尚萬強因為偷一塊麵包坐了十九年牢，出獄後被主教的寬恕感動，改名重新做人，成了市長，收養了孤女珂賽特；警探賈維爾卻一輩子追捕他。故事一路寫到巴黎的街壘起義
結局=賈維爾在法律與良心的矛盾中投河自盡；珂賽特和馬里尤斯結婚，尚萬強在他們身邊安詳離世
主題=寬恕與救贖、法律與良心、社會不公、愛
看法=一個人被怎麼對待，真的可能改變他的一生——主教的那對銀燭台就是證明
@鐘樓怪人|巴黎聖母院|作品
作者=法國的雨果
類型=長篇小說
地區=西方
年代=1831 年
簡介=以巴黎聖母院為舞台的浪漫主義悲劇
故事=醜陋的敲鐘人加西莫多愛上美麗的吉普賽女郎艾絲美拉達，而主教代理弗羅洛也瘋狂迷戀她，得不到就陷害她
結局=艾絲美拉達被處死，加西莫多把弗羅洛推下鐘樓，後來人們在墓穴裡發現他抱著她的屍骨
主題=外表與內心、偏見、執念與真愛
看法=最醜的人心最乾淨，最體面的人最可怕——雨果很喜歡用這種對比打醒讀者
@基督山恩仇記|基督山伯爵|作品
作者=法國的大仲馬
類型=長篇小說
地區=西方
年代=1844 年
簡介=最有名的復仇小說之一
故事=年輕水手唐泰斯被嫉妒他的人誣陷，在婚禮上被捕，關進伊夫堡監獄十四年。他在獄中得到神父的教導和寶藏的秘密，越獄後化身基督山伯爵，一一向仇人復仇
結局=復仇完成後，他發現報復也傷害了無辜的人，選擇寬恕，留下「等待和希望」這句話離開
主題=復仇、正義、等待與希望
看法=爽的是復仇，深的是最後那一步：他明白自己不是上帝
@傲慢與偏見|傲慢與偏見|作品
作者=英國的珍·奧斯汀
類型=長篇小說
地區=西方
年代=1813 年
簡介=英國最受喜愛的愛情小說之一
故事=班奈特家有五個女兒要嫁人。聰明的二女兒伊莉莎白一開始覺得富有的達西先生傲慢無禮，達西也看不起她的家庭；經過誤會、拒絕和真相大白，兩人慢慢看清對方
結局=兩人放下傲慢和偏見結婚
主題=第一印象的偏見、驕傲、婚姻與金錢、女性的處境
看法=書名說得很準：傲慢和偏見兩個人都有，愛情是從承認自己錯了開始的
@簡愛|簡·愛|作品
作者=英國的夏綠蒂·勃朗特
類型=長篇小說
地區=西方
年代=1847 年
簡介=一個孤女追求尊嚴和平等愛情的故事
故事=孤女簡愛從小受虐，長大當了桑菲爾德莊園的家庭教師，和主人羅徹斯特相愛；婚禮上才知道他的瘋妻子被關在閣樓，簡愛不願當情婦而離開
結局=莊園失火，羅徹斯特救人失明、妻子身亡，簡愛回到他身邊，兩人平等地結婚
主題=女性的獨立與尊嚴、平等的愛、階級
看法=「我們的靈魂是平等的」這句話，在當時說出口需要很大的勇氣
@咆哮山莊|呼嘯山莊|作品
作者=英國的艾蜜莉·勃朗特
類型=長篇小說
地區=西方
年代=1847 年
簡介=一部充滿激情和報復的愛情小說
故事=被收養的孤兒希斯克里夫和凱瑟琳一起長大、深深相愛，凱瑟琳卻嫁給了有錢的林頓。希斯克里夫離開後發財回來，對兩個家族展開長達兩代人的報復
結局=希斯克里夫在思念凱瑟琳中死去，下一代的年輕人終於擺脫仇恨相愛
主題=狂烈的愛、復仇、階級、愛與恨的界線
看法=它不是浪漫的愛情，是會毀掉人的那種愛，所以才讓人忘不了
@雙城記|雙城記|作品
作者=英國的狄更斯
類型=長篇小說
地區=西方
年代=1859 年
簡介=以法國大革命為背景，倫敦和巴黎兩座城市的故事
故事=法國貴族後代達爾內放棄爵位到英國生活，娶了露西；革命爆發後他回法國救人，卻被革命法庭判死刑。長得很像他的英國律師卡頓也愛著露西
結局=卡頓偷偷替達爾內上了斷頭台，成全露西的幸福
主題=犧牲與救贖、革命的暴力、愛
看法=開頭「這是最好的時代，也是最壞的時代」很有名，但最打動我的是卡頓最後的選擇
@孤雛淚|霧都孤兒,苦海孤雛,奧利佛·崔斯特|作品
作者=英國的狄更斯
類型=長篇小說
地區=西方
年代=1838 年
簡介=狄更斯揭露倫敦底層孤兒處境的小說
故事=孤兒奧利佛在救濟院長大，因為「再要一碗粥」被趕走，逃到倫敦後落入費金的扒手集團，被逼著偷東西
結局=好心的布朗洛先生收養他，查出他的身世，壞人受到懲罰
主題=貧窮與社會不公、善良能不能在惡劣環境中保住
看法=狄更斯用一個孩子的眼睛，讓讀者沒辦法假裝看不到窮人
@塊肉餘生記|大衛·科波菲爾,塊肉餘生錄|作品
作者=英國的狄更斯
類型=長篇小說
地區=西方
年代=1850 年
簡介=帶有狄更斯自傳色彩的成長小說
故事=大衛從小失去父母，受繼父虐待、被送去工廠做苦工，逃到姨婆家後靠努力讀書，一路經歷愛情、失去和友誼，成為作家
結局=第一任妻子病逝後，他娶了一直默默支持他的艾妮絲，生活安定
主題=成長、堅持、善良與人性
看法=它像在告訴讀者：童年再苦，也不代表一輩子就這樣
@罪與罰|罪與罰|作品
作者=俄國的杜斯妥也夫斯基
類型=長篇小說
地區=西方
年代=1866 年
簡介=心理小說的經典，寫一個殺人犯內心的煎熬
故事=窮大學生拉斯柯尼科夫相信「不平凡的人有權越過道德」，殺了放高利貸的老太婆，之後陷入恐懼、高燒和罪惡感，和警探波費利玩心理戰
結局=在善良的妓女索妮雅的感化下，他自首被流放西伯利亞，開始走向心靈的重生
主題=罪惡感、道德、良心、救贖
看法=真正的懲罰不是坐牢，而是殺人之後他再也沒辦法跟自己相處
@卡拉馬助夫兄弟們|卡拉馬佐夫兄弟|作品
作者=俄國的杜斯妥也夫斯基
類型=長篇小說
地區=西方
年代=1880 年
簡介=杜斯妥也夫斯基最後也最偉大的小說，討論信仰與人性
故事=荒淫的父親費多爾被殺，三個兒子——衝動的德米特里、懷疑上帝的伊凡、虔誠的阿遼沙——各自被捲入。真正的兇手是私生子斯麥爾佳科夫，卻是德米特里被判有罪
結局=德米特里被冤判，伊凡因罪惡感精神崩潰，阿遼沙對孩子們講述愛與記憶
主題=信仰與懷疑、自由意志、罪與責任、父子關係
看法=伊凡問的「如果沒有上帝，是不是什麼都可以做」，到今天還是很難回答
@戰爭與和平|戰爭與和平|作品
作者=俄國的托爾斯泰
類型=長篇小說
地區=西方
年代=1869 年
簡介=以拿破崙入侵俄國為背景的史詩小說
故事=以幾個貴族家庭為中心，寫皮埃爾、安德烈公爵、娜塔莎等人在戰爭與和平年代的愛情、迷惘和成長，從奧斯特利茨戰役寫到拿破崙攻進莫斯科又敗退
結局=安德烈戰傷而死，皮埃爾和娜塔莎結婚，在平凡的家庭生活中找到意義
主題=歷史與個人、人生的意義、愛與死亡
看法=很長，但它想說的很簡單：歷史不是英雄寫的，是無數普通人過日子過出來的
@安娜·卡列尼娜|安娜卡列尼娜,安娜·卡列妮娜|作品
作者=俄國的托爾斯泰
類型=長篇小說
地區=西方
年代=1877 年
簡介=托爾斯泰寫婚姻、外遇和社會的經典
故事=貴族婦人安娜愛上年輕軍官渥倫斯基，離開冷漠的丈夫和兒子，卻被上流社會排斥，愛情也在猜疑中變質；另一條線是列文追求真誠生活的故事
結局=安娜在絕望中臥軌自殺；列文在家庭和信仰中找到平靜
主題=愛情與婚姻、社會的虛偽、人生的意義
看法=開頭「幸福的家庭都相似，不幸的家庭各有各的不幸」說盡了一切
@老人與海|老人與海|作品
作者=美國的海明威
類型=中篇小說
地區=西方
年代=1952 年
簡介=海明威的代表作，幫他拿到普立茲獎，也是他得諾貝爾文學獎的重要原因
故事=古巴老漁夫聖地牙哥連續 84 天沒捕到魚，獨自出海，終於釣到一條比船還大的馬林魚，和牠搏鬥了三天兩夜才把牠殺死綁在船邊
結局=回航途中鯊魚一次又一次來搶食，他拚命反擊，回到港口時只剩一副魚骨，他回家睡覺，夢見非洲的獅子
主題=人的尊嚴與堅持、失敗中的勝利、人與自然
看法=「人可以被毀滅，但不能被打敗」——結果輸了，但他沒有放棄，這才是重點
@大亨小傳|了不起的蓋茨比,大亨小傳|作品
作者=美國的費茲傑羅
類型=長篇小說
地區=西方
年代=1925 年
簡介=寫美國「爵士時代」繁華與空虛的經典
故事=神秘富豪蓋茨比每週在豪宅開派對，其實只為了再見到舊愛黛西——她已經嫁給有錢的湯姆。敘述者尼克看著蓋茨比為過去的夢想付出一切
結局=黛西開車撞死人，蓋茨比替她頂罪，被死者的丈夫槍殺；葬禮上幾乎沒有人來
主題=美國夢的幻滅、金錢與階級、無法重來的過去
看法=蓋茨比要的不是黛西，是回到過去；那是錢買不到的東西
@麥田捕手|麥田裡的守望者|作品
作者=美國的沙林傑
類型=長篇小說
地區=西方
年代=1951 年
簡介=寫青少年迷惘與叛逆的經典
故事=16 歲的霍爾頓被學校退學，不敢回家，一個人在紐約遊蕩三天，看什麼都覺得「假」，只有妹妹菲比讓他覺得真實
結局=他看著妹妹坐旋轉木馬，終於感到快樂；後來他在療養院裡講出這段故事
主題=成長的痛苦、對虛偽成人世界的抗拒、守護純真
看法=他想當在麥田邊接住孩子的人，其實是他自己最需要被接住
@一九八四|1984,一九八四年|作品
作者=英國的喬治·歐威爾
類型=反烏托邦小說
地區=西方
年代=1949 年
簡介=最有名的反烏托邦小說，「老大哥在看著你」就出自這裡
故事=在極權國家大洋國，黨透過電幕監視每個人、改寫歷史、發明「新語」限制思想。真理部的溫斯頓偷偷寫日記、和茱莉亞相戀，想反抗黨
結局=他們被思想警察抓走，溫斯頓在 101 號房被酷刑擊垮，出賣了茱莉亞，最後真心「愛上了老大哥」
主題=極權與監控、思想控制、真相與語言、個人自由
看法=最恐怖的不是被監視，是最後連你自己的想法都不是你的
@動物農莊|動物農場,動物莊園|作品
作者=英國的喬治·歐威爾
類型=寓言小說
地區=西方
年代=1945 年
簡介=用動物寓言諷刺革命和極權的中篇小說
故事=農莊的動物們起來推翻人類農場主，口號是「所有動物一律平等」。豬成了領導者，拿破崙趕走對手雪球後慢慢變成新的獨裁者
結局=口號被改成「所有動物一律平等，但有些動物比其他動物更平等」，豬和人坐在一起喝酒，動物們已經分不出誰是豬誰是人
主題=權力腐化、革命被背叛、宣傳與謊言
看法=它短到一個下午就能讀完，但會讓你以後看任何口號都多想一下
@美麗新世界|美麗新世界|作品
作者=英國的赫胥黎
類型=反烏托邦小說
地區=西方
年代=1932 年
簡介=和《一九八四》齊名的反烏托邦小說
故事=未來世界的人在工廠裡被培育、從小被灌輸階級觀念，人人吃快樂藥「索麻」、沒有家庭和痛苦。在保留區長大的「野人」約翰來到這個世界，無法接受
結局=約翰想逃離卻被當成奇觀圍觀，最後上吊自殺
主題=用快樂控制人、科技與人性、自由要不要包含痛苦
看法=歐威爾怕我們被痛苦控制，赫胥黎怕我們被快樂控制——後者好像更接近現在
@變形記|蛻變|作品
作者=奧地利（布拉格）的卡夫卡
類型=中篇小說
地區=西方
年代=1915 年
簡介=卡夫卡最有名的作品，一個人變成蟲之後的故事
故事=推銷員葛雷戈某天早上醒來發現自己變成一隻巨大的蟲。他原本靠薪水養全家，變成蟲後家人從同情、害怕到嫌棄
結局=他在孤獨中死去，家人反而鬆了一口氣，出門郊遊、計畫新生活
主題=異化、被當成工具的人、家庭關係的冷漠、存在的荒謬
看法=變成蟲是荒謬的，但家人的反應一點都不荒謬，這才是最刺痛的地方
@異鄉人|局外人|作品
作者=法國的卡繆
類型=中篇小說
地區=西方
年代=1942 年
簡介=存在主義和荒謬哲學的代表小說
故事=莫梭在母親葬禮上沒有哭，之後若無其事地游泳、看電影、交女朋友。在海灘上，他因為陽光刺眼開槍殺了一個阿拉伯人
結局=法庭更在意他在葬禮上沒哭，判他死刑；行刑前他接受了世界的冷漠，覺得自己是幸福的
主題=荒謬、社會對「不一樣的人」的審判、誠實面對自己
看法=他被判死刑不完全是因為殺人，而是因為他不肯照社會期待的方式表演情緒
@小王子|小王子|作品
作者=法國的聖修伯里
類型=中篇小說（童話）
地區=西方
年代=1943 年
簡介=寫給大人的童話，全世界翻譯最多的書之一
故事=飛行員迫降在撒哈拉沙漠，遇到從 B-612 小行星來的小王子。小王子講他照顧的玫瑰，和他在各個星球遇到的奇怪大人，還有在地球上遇到教他「馴養」的狐狸
結局=小王子讓蛇咬了自己，回到他的星球和玫瑰身邊；飛行員從此抬頭看星星都會想起他的笑聲
主題=愛與責任、大人忘了的童心、真正重要的東西眼睛看不見
看法=「你為你的玫瑰花費的時間，讓你的玫瑰變得那麼重要」——講的其實是所有的關係
@百年孤寂|百年孤獨|作品
作者=哥倫比亞的馬奎斯（賈西亞·馬奎斯）
類型=長篇小說
地區=西方（拉丁美洲）
年代=1967 年
簡介=魔幻現實主義的代表作
故事=波恩地亞家族在虛構的小鎮馬康多生活了七代，經歷建城、內戰、香蕉公司和屠殺，家族裡一再出現同樣的名字、同樣的瘋狂和孤獨
結局=最後一代的孩子長著豬尾巴出生，被螞蟻吃掉；家族最後一人讀懂了預言羊皮卷，馬康多被颶風抹去
主題=孤獨、歷史的重複、家族與宿命、拉丁美洲的歷史
看法=名字一直重複很容易讀亂，但這正是它想說的：不記取教訓的人，會一直重複同樣的命運
@唐璜|唐璜|作品
作者=英國的拜倫
類型=長篇敘事詩
地區=西方
年代=1819 年到 1824 年
簡介=拜倫的諷刺長詩，借花花公子唐璜的冒險諷刺歐洲社會
故事=年輕的西班牙貴族唐璜因為戀愛醜聞被送出國，經歷海難、被賣為奴、進入俄國宮廷，最後到了英國上流社會
結局=拜倫還沒寫完就過世了，作品停在英國的部分
主題=諷刺虛偽的上流社會、愛情與慾望、自由
看法=它是在笑整個社會，唐璜反而常常是被動的那個
@神曲|神曲|作品
作者=義大利的但丁
類型=長篇敘事詩
地區=西方
年代=十四世紀初
簡介=中世紀最偉大的詩作，寫一趟穿越地獄、煉獄和天堂的旅程
故事=但丁在人生的中途迷失在黑暗森林，由古羅馬詩人維吉爾帶領走過地獄九層、爬上煉獄山，再由心愛的貝雅特麗齊帶他遊歷天堂
結局=他在天堂最高處看見上帝的光，明白推動太陽和群星的是愛
主題=罪與懲罰、救贖、信仰、愛
看法=很多人只記得地獄篇，因為壞人的下場最好看；但它真正的終點是愛
@伊利亞德|伊里亞德,伊利亞特|作品
作者=古希臘的荷馬（傳說）
類型=史詩
地區=西方
年代=大約西元前八世紀
簡介=西方文學最早的史詩之一，寫特洛伊戰爭
故事=特洛伊戰爭第十年，希臘第一勇士阿基里斯因為被統帥奪走女俘而拒絕出戰，希臘節節敗退；好友帕特羅克洛斯戰死後，他重新上陣殺了特洛伊王子赫克托
結局=特洛伊老國王冒死來求回兒子的屍體，阿基里斯被感動歸還，史詩停在赫克托的葬禮（木馬屠城不在這部）
主題=憤怒與榮耀、戰爭的殘酷、生命的短暫
看法=第一句就是「憤怒」，整部史詩其實在講一個人怎麼從憤怒走到憐憫
@奧德賽|奧德修紀|作品
作者=古希臘的荷馬（傳說）
類型=史詩
地區=西方
年代=大約西元前八世紀
簡介=荷馬史詩之一，英雄奧德修斯回家的十年旅程
故事=特洛伊戰爭結束後，想出木馬計的奧德修斯在回家路上漂流十年，遇到獨眼巨人、女妖賽蓮、女巫喀耳刻，同伴一個個死去；家中的妻子潘妮洛普被一群求婚者包圍
結局=他喬裝成乞丐回到家鄉，和兒子一起殺光求婚者，和妻子重逢
主題=回家、智慧與堅持、忠誠
看法=英雄不只是會打仗，還要能撐過漫長的回家路
@浮士德|浮士德|作品
作者=德國的歌德
類型=詩劇
地區=西方
年代=1808 年（第一部）和 1832 年（第二部）
簡介=歌德花了六十年寫成的代表作
故事=學者浮士德對知識感到空虛，和魔鬼梅菲斯特訂約：魔鬼滿足他一切願望，但只要他說出「停一停吧，你真美」，靈魂就歸魔鬼。他經歷愛情（害了少女葛麗卿）、權力和事業
結局=晚年的浮士德在為人民開墾土地的理想中說出了那句話而死，但天使因為他不斷追求而救走了他的靈魂
主題=永不滿足的追求、善與惡、人生的意義
看法=歌德說「凡是不斷努力的人，我們都能救他」，追求本身就是意義
@少年維特的煩惱|少年維特之煩惱|作品
作者=德國的歌德
類型=書信體小說
地區=西方
年代=1774 年
簡介=讓歌德一夜成名的小說，狂飆運動的代表作
故事=年輕的維特在鄉下愛上了已經訂婚的綠蒂，明知沒有結果還是越陷越深，離開又回來，在社會上也處處碰壁
結局=綠蒂嫁人後，維特在絕望中借了綠蒂丈夫的手槍自殺
主題=無法實現的愛、情感與社會的衝突、青春的苦悶
看法=它寫出了年輕人那種「全世界都不懂我」的痛，所以當年才會引起那麼大的共鳴
@魯賓遜漂流記|魯濱遜漂流記|作品
作者=英國的笛福
類型=長篇小說
地區=西方
年代=1719 年
簡介=最有名的荒島求生故事
故事=魯賓遜出海遇到船難，一個人漂到荒島，自己蓋房子、種糧食、養羊，後來救了一個土著，取名星期五當夥伴
結局=他在島上生活了 28 年，最後搭上一艘英國船回家
主題=求生、勤勞與意志、人與自然
看法=它像一本生存手冊，也讓人想到：一個人能做的事，比自己以為的多
@格列佛遊記|格列佛遊記|作品
作者=英國的斯威夫特
類型=諷刺小說
地區=西方
年代=1726 年
簡介=借奇幻旅行諷刺英國社會的小說
故事=船醫格列佛去了小人國、大人國、飛島國和慧駰國（由有理性的馬統治），每到一處都看見人類社會的荒謬
結局=他回到英國後，覺得人類跟慧駰國裡野蠻的「犽猢」一樣，再也無法和家人親近
主題=諷刺政治和人性、文明的虛偽
看法=很多人以為是童話，其實它是在罵人，罵得很聰明
@愛麗絲夢遊仙境|愛麗絲漫遊奇境記|作品
作者=英國的路易斯·卡羅
類型=童話小說
地區=西方
年代=1865 年
簡介=充滿文字遊戲和荒謬幻想的經典童話
故事=小女孩愛麗絲追著一隻拿懷錶的兔子掉進洞裡，在仙境裡忽大忽小，遇到柴郡貓、瘋帽匠和動不動就要砍頭的紅心皇后
結局=在荒唐的審判中她大喊「你們只不過是一副撲克牌」，醒來發現是一場夢
主題=想像力、成長的困惑、對規則和權威的嘲諷
看法=大人讀它會發現，仙境的荒謬其實跟現實世界很像
@哈利波特|哈利·波特,哈利波特系列|作品
作者=英國的 J·K·羅琳
類型=奇幻小說系列（共七集）
地區=西方
年代=1997 年到 2007 年
簡介=全世界最暢銷的奇幻小說系列
故事=孤兒哈利十一歲時才知道自己是巫師，進入霍格華茲魔法學校，和榮恩、妙麗成為好友。他的父母被黑巫師佛地魔殺死，而佛地魔一直想復活、殺死哈利
結局=第七集裡哈利找出並摧毀佛地魔的分靈體，在霍格華茲大戰中打敗佛地魔
主題=愛與犧牲、友誼、選擇比天賦重要、面對死亡
看法=鄧不利多說「決定我們是什麼樣的人的，是我們的選擇，而不是能力」——這是整個系列的核心
@魔戒|指環王|作品
作者=英國的托爾金
類型=奇幻小說
地區=西方
年代=1954 年到 1955 年
簡介=現代奇幻文學的奠基之作
故事=哈比人佛羅多繼承了黑暗魔君索倫的至尊魔戒，必須和護戒隊一起把魔戒送到末日火山摧毀。一路上魔戒不斷誘惑持有的人
結局=佛羅多在最後一刻也抵擋不住魔戒的誘惑，是咕嚕搶戒指時跌進火山，魔戒才被摧毀；索倫滅亡
主題=權力的誘惑與腐化、平凡人的勇氣、友誼
看法=拯救世界的不是最強的人，是最不起眼的哈比人，這點我很喜歡
@紅樓夢|石頭記,紅樓|作品
作者=清代的曹雪芹（一般認為後四十回是高鶚等人續寫）
類型=長篇章回小說
地區=中國
年代=清朝乾隆年間（十八世紀中葉）
簡介=中國古典四大名著之一，被認為是中國古典小說的巔峰
故事=以賈寶玉、林黛玉、薛寶釵的愛情和婚姻悲劇為主線，寫賈、史、王、薛四大家族，特別是賈府從榮華富貴走向衰敗
結局=林黛玉在寶玉和寶釵成婚那天病死，賈府被抄家衰落，寶玉最後出家
主題=繁華如夢、愛情悲劇、家族興衰、女性的命運
看法=「滿紙荒唐言，一把辛酸淚」，越看越覺得它在寫一場終究要醒的夢
@三國演義|三國志演義,三國|作品
作者=元末明初的羅貫中
類型=長篇章回小說
地區=中國
年代=元末明初（十四世紀）
簡介=中國古典四大名著之一，以三國歷史為本的歷史小說
故事=從東漢末年黃巾之亂寫起，劉備、關羽、張飛桃園結義，諸葛亮出山，魏蜀吳三國爭霸，有赤壁之戰、三顧茅廬、草船借箭等故事
結局=三國最後都滅亡，由司馬炎建立的晉朝統一天下
主題=忠義、智謀、天下大勢分久必合合久必分
看法=小說比正史更愛劉備和諸葛亮，讀的時候要記得它是「演義」，不全是歷史
@西遊記|西遊記|作品
作者=明代的吳承恩（一般的說法）
類型=長篇章回小說（神魔小說）
地區=中國
年代=明朝（十六世紀）
簡介=中國古典四大名著之一，唐僧師徒西天取經的神魔小說
故事=石猴孫悟空大鬧天宮被壓在五行山下，後來和豬八戒、沙悟淨一起保護唐三藏去西天取經，一路經歷九九八十一難，打敗各種妖怪
結局=師徒抵達西天取得真經，各自修成正果，孫悟空成為鬥戰勝佛
主題=修行與成長、克服心魔、團隊合作
看法=很多人說孫悟空代表人的心，取經的路其實是把那顆心馴服的過程
@水滸傳|水滸,水滸全傳|作品
作者=元末明初的施耐庵（一般的說法）
類型=長篇章回小說
地區=中國
年代=元末明初（十四世紀）
簡介=中國古典四大名著之一，梁山好漢的故事
故事=北宋末年，林沖、武松、魯智深、宋江等一百零八位好漢因為各種原因被逼上梁山，聚義反抗貪官
結局=宋江帶大家接受朝廷招安，去打方臘，好漢們死傷大半，宋江最後被奸臣毒死
主題=官逼民反、忠義、俠義與暴力
看法=前半很熱血，後半很悲涼——招安之後，好漢就不再是好漢了
@金瓶梅|金瓶梅詞話|作品
作者=明代的蘭陵笑笑生（真實身分不明）
類型=長篇章回小說
地區=中國
年代=明朝萬曆年間
簡介=中國第一部以家庭日常生活為主的長篇小說
故事=從《水滸傳》武松殺嫂的故事延伸，寫西門慶一家和潘金蓮、李瓶兒、春梅等女性的生活，揭露明代社會的腐敗
結局=西門慶縱慾而死，家道衰敗，眾人各自走向悲慘結局
主題=慾望、家庭與社會的腐敗、世態炎涼
看法=它常被貼上「色情」的標籤，但其實是一面很誠實的社會鏡子
@儒林外史|儒林外史|作品
作者=清代的吳敬梓
類型=長篇章回小說（諷刺小說）
地區=中國
年代=清朝乾隆年間
簡介=中國古典諷刺小說的代表作，諷刺科舉制度下的讀書人
故事=寫一群讀書人為了功名利祿的醜態，最有名的是范進考了幾十年終於中舉，高興到發瘋
結局=沒有統一的主角和結局，最後寫幾個市井奇人，表達理想的人生
主題=諷刺科舉、功名利祿、讀書人的虛偽
看法=范進中舉那一段好笑又心酸，今天的升學壓力好像也沒差多少
@聊齋誌異|聊齋,聊齋志異|作品
作者=清代的蒲松齡
類型=文言短篇小說集
地區=中國
年代=清朝初年
簡介=寫鬼狐妖怪的短篇小說集，有近五百篇
故事=寫狐仙、鬼魂、花妖和人之間的愛情和恩怨，像〈聶小倩〉〈畫皮〉〈嬰寧〉，借鬼狐故事寫人間的不公
結局=是短篇集，每篇各自結束
主題=借鬼說人、諷刺科舉和官場、人情與愛情
看法=書裡的鬼狐常常比人有情有義，這就是蒲松齡想說的
@活著|活著|作品
作者=中國的余華
類型=長篇小說
地區=中國
年代=1993 年
簡介=余華的代表作，寫一個普通人經歷大時代苦難的一生
故事=地主少爺福貴年輕時吃喝嫖賭把家產輸光，之後經歷國共內戰、大躍進、文化大革命，父母、妻子家珍、兒子有慶、女兒鳳霞、女婿和外孫一個個離他而去
結局=最後只剩福貴和一頭老牛相依為命，他把牛也叫做「福貴」，平靜地講述自己的一生
主題=活著本身的意義、苦難與忍受、命運
看法=余華說「人是為活著本身而活著，而不是為了活著之外的任何事物」，這本書就是這句話
@圍城|圍城|作品
作者=中國的錢鍾書
類型=長篇小說
地區=中國
年代=1947 年
簡介=中國現代最有名的諷刺小說之一
故事=留學歸國的方鴻漸拿著買來的假文憑回國，在愛情、工作和婚姻裡處處失敗，和孫柔嘉結婚後兩人不斷爭吵
結局=夫妻大吵一架後分開，老鐘慢了五個鐘頭才敲響，象徵人生的無奈
主題=婚姻和人生像圍城、知識分子的空虛
看法=「城外的人想衝進去，城裡的人想逃出來」，講婚姻，也講人生每一個選擇
@阿Q正傳|阿Q,阿Q正傳|作品
作者=中國的魯迅
類型=中篇小說
地區=中國
年代=1921 年
簡介=魯迅最有名的小說，創造了「阿Q精神」這個詞
故事=未莊的雇工阿Q被人欺負，卻總是用「精神勝利法」安慰自己（「兒子打老子」）；辛亥革命時他想跟著「革命」，卻什麼都不懂
結局=他被冤枉搶劫，糊里糊塗地被槍斃，畫押時還努力把圈畫圓
主題=國民的劣根性、精神勝利法、革命的不徹底
看法=魯迅寫的不只是阿Q，是每個不敢面對失敗、只會自我安慰的人
@三體|三體三部曲,地球往事|作品
作者=中國的劉慈欣
類型=長篇科幻小說（三部曲）
地區=中國
年代=2006 年到 2010 年
簡介=第一部拿到雨果獎的亞洲長篇小說
故事=文革中失去父親的科學家葉文潔，對人類絕望，用紅岸基地向宇宙發出信號，引來即將入侵的三體文明。三體人用「智子」鎖死地球的科學，人類開始面壁計畫、黑暗森林威懾
結局=三部曲的最後，宇宙被高等文明的「降維打擊」摧毀，程心和關一帆在小宇宙中迎來宇宙的終結與重生
主題=黑暗森林法則、文明與生存、人性在宇宙尺度下的渺小
看法=它的厲害是把一個冷酷的想法推到極致：在宇宙裡，善意可能是最危險的東西
@挪威的森林|挪威森林|作品
作者=日本的村上春樹
類型=長篇小說
地區=日本
年代=1987 年
簡介=村上春樹最暢銷的小說
故事=大學生渡邊在好友木月自殺後，和木月的女友直子相愛；直子精神狀況不穩住進療養院，渡邊同時被活潑的綠吸引
結局=直子自殺，渡邊在混亂中打電話給綠，卻不知道自己身在何處
主題=失去與哀悼、青春的孤獨、死亡是生的一部分
看法=它很憂傷，但不絕望：活著的人最後還是要選擇繼續活下去
@人間失格|人間失格|作品
作者=日本的太宰治
類型=中篇小說
地區=日本
年代=1948 年
簡介=太宰治的代表作，帶有自傳色彩
故事=主角大庭葉藏從小害怕人，只好用搞笑討好別人；長大後酗酒、自殺未遂、沉溺藥物，一步步墮落
結局=他被送進精神病院，覺得自己「已經失去做人的資格」
