結局=安迪在暴雨夜從下水道逃出，揭發典獄長；瑞德假釋後照約定去墨西哥海邊找他
主題=希望、自由、友誼、制度化
看法=「希望是好東西，也許是最好的東西」——這部片讓人相信，希望要靠一天一天地挖
@阿甘正傳|阿甘正傳|作品
