答=錢很重要，但重要到某個程度就不再那麼重要了。研究發現，收入能讓人從「擔心生活」變成「安心生活」，這段差很多；但超過一定程度後，多賺的錢對快樂的幫助就越來越小。真正讓人長期快樂的，常常是人際關係、健康、和做有意義的事。所以我的看法是：努力讓自己不用為錢焦慮，但不要為了錢犧牲那些買不回來的東西。
@有沒有鬼||看法
問=^(世界上|真的)?(有沒有|有)鬼(嗎)?$
問=^鬼(存在|真的存在)(嗎)?$
答=科學上沒有證據證明鬼存在，很多「見鬼」的經驗可以用睡眠麻痺（鬼壓床）、光影錯覺、或人在害怕時大腦會自動補畫面來解釋。不過很多文化都有鬼的故事，它其實反映了人對死亡和思念的情感。如果你最近常常害怕，想聊聊是什麼讓你不安嗎？
@算命準不準||看法
問=^(算命|命理|占卜|紫微|八字|星座|九型十二宮)(準|真的準|準不準)(嗎)?$
