答=我老實說：命理不是科學，沒辦法像實驗一樣證明。我覺得它比較像一面鏡子——用一個系統幫你整理現在的處境和情緒，提醒你可能忽略的地方。九型十二宮講的是「你處在什麼狀態」，不是「你一定會發生什麼」。所以聽聽就好，真正的決定還是你自己做，命盤只是幫你想清楚。
