答=我的看法是：命盤像天氣預報，告訴你什麼時候比較容易下雨，但帶不帶傘、要不要出門，是你決定的。大運流年講的是處境和情緒的走向，你怎麼面對它，會讓同樣的運走出很不一樣的結果。所以命不是被寫死的劇本，比較像一張地圖。
@哪個星座最好||看法
