答=沒有最好的星座，每個星座都有它擅長和容易卡住的地方：牡羊有衝勁但沒耐心、金牛穩定但固執、雙子聰明但三分鐘熱度……而且同一個星座的人差異也很大，因為一個人的命盤不只有太陽星座。如果想看你自己，告訴我生日，我用九型十二宮幫你看。
@先有雞還是先有蛋||看法
問=^先有雞(還是|或)先有蛋$
答=照演化論，先有蛋。很久以前，一隻「很像雞但還不是雞」的鳥下了一顆蛋，蛋裡的基因發生突變，孵出了第一隻真正的雞。所以那顆蛋比雞先出現——只是下蛋的不是雞。
@你覺得我笨嗎||關心
